.excel-grid-container {
    background-color: #ffffff;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    font-family: 'Roboto', sans-serif;
    color: #333;
}
.grid-header {
    /* Cabecera compacta en dos filas apiladas: leyenda arriba y fecha + pestañas +
       botones debajo, cada una ocupando todo el ancho disponible y envolviendo sus
       propios elementos internamente si hace falta. Esto evita el problema de meter
       las dos cosas en la misma línea con anchos "flexibles": si una de las dos no
       cabe, en vez de envolver de línea se salía del recuadro y quedaba invisible.
       Apilarlas siempre en dos filas cortas es lo más fino y fiable. */
    display: flex;
    flex-direction: column;
    align-items: stretch;
    padding: 5px 12px;
    background-color: #f5f7fa;
    border-bottom: 2px solid #cfd8dc;
    row-gap: 4px;
    /* flex-shrink: 0 -- la cabecera NUNCA debe encogerse cuando la tabla (con muchas
       filas) pida más espacio del que hay disponible en el widget: quien tiene que
       ceder y hacer scroll es la tabla (.table-wrapper, que ya tiene flex-grow:1 y
       overflow:auto para eso), no la cabecera. */
    flex-shrink: 0;
}
.legend-container {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px 10px;
    font-size: 11px;
    line-height: 1.1;
    font-weight: 500;
    color: #455a64;
    min-width: 0;
}
.legend-item { display: flex; align-items: center; gap: 4px; white-space: nowrap; }
.color-box { width: 9px; height: 9px; border-radius: 2px; flex: 0 0 auto; }
.date-picker-container {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    font-weight: 500;
    color: #455a64;
}
.form-control-date {
    padding: 3px 8px;
    font-size: 12px;
    border: 1px solid #cfd8dc;
    border-radius: 4px;
    outline: none;
    color: #455a64;
    cursor: pointer;
    font-family: inherit;
    background-color: #ffffff;
}
.form-control-date:focus { border-color: #607d8b; }
/* --- Pestañas (Calendario / Resumen Mensual / Resumen Campaña) --- */
.tabs-container {
    display: flex;
    gap: 4px;
    background-color: #eceff1;
    padding: 3px;
    border-radius: 6px;
}
.tab-btn {
    padding: 4px 12px;
    background-color: transparent;
    color: #455a64;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 12px;
    font-weight: bold;
    font-family: inherit;
    white-space: nowrap;
    transition: background-color 0.15s ease, color 0.15s ease;
}
.tab-btn:hover {
    background-color: #cfd8dc;
}
.tab-btn-active,
.tab-btn-active:hover {
    background-color: #263238;
    color: #ffffff;
}
#btn-refrescar-numeros:hover { background-color: #0a3880; }
#btn-refrescar-numeros:disabled { cursor: default; }
#btn-export-csv:hover { background-color: #164a1a; }
#btn-export-pdf:hover { background-color: #8f1414; }
/* --- Placeholder de Resumen Campaña (aun sin datos) --- */
.placeholder-campana {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    min-height: 300px;
    color: #78909c;
    text-align: center;
    gap: 8px;
    padding: 40px;
}
.placeholder-campana-icono { font-size: 40px; }
.placeholder-campana-titulo { font-size: 18px; font-weight: bold; color: #455a64; }
.placeholder-campana-texto { font-size: 13px; max-width: 420px; }
.table-wrapper {
    flex-grow: 1;
    overflow: auto;
    min-height: 0;
    min-width: 0;
    scrollbar-width: thin;
    scrollbar-color: #90a4ae #eceff1;
}
.table-wrapper::-webkit-scrollbar {
    height: 10px;
    width: 10px;
}
.table-wrapper::-webkit-scrollbar-track {
    background: #eceff1;
}
.table-wrapper::-webkit-scrollbar-thumb {
    background-color: #90a4ae;
    border-radius: 5px;
}
.table-wrapper::-webkit-scrollbar-thumb:hover {
    background-color: #78909c;
}
table {
    border-collapse: collapse;
    width: 100%;
    min-width: max-content;
    margin-bottom: 40px;
}
th, td {
    box-sizing: border-box;
    border: 1px solid #78909c;
    padding: 4px 2px;
    text-align: center;
    font-size: 12px;
    min-width: 32px;
    height: 25px;
}
.col-fixed-1 { position: sticky; left: 0; width: 65px; min-width: 65px; background-color: #263238; color: #ffffff; font-weight: bold; z-index: 20; }
.col-fixed-2 { position: sticky; left: 65px; width: 100px; min-width: 100px; background-color: #263238; color: #ffffff; font-weight: bold; z-index: 20; }
.col-spacer { border: none; background: transparent; min-width: 0; padding: 0; }
thead .col-spacer { background: transparent; }
.col-fixed-3 { position: sticky; left: 165px; width: 160px; min-width: 160px; background-color: #263238; color: #ffffff; font-weight: bold; text-align: left; padding-left: 8px; z-index: 20; border-right: 2px solid #ffffff; }
th {
    background-color: #263238;
    color: #ffffff;
    font-weight: bold;
    position: sticky;
    top: 0;
    z-index: 10;
}
th.col-fixed-1, th.col-fixed-2, th.col-fixed-3 {
    z-index: 30;
}
.sum-col { background-color: #c8e6c9; font-weight: bold; vertical-align: middle; }
.val-caudal { color: #0d47a1; font-weight: 500; }
.val-manual { color: #b71c1c; font-weight: bold; }
.val-guarda-caudal { color: #4a148c; font-weight: bold; }
.box-caudal { background-color: #0d47a1; }
.box-manual { background-color: #b71c1c; }
.box-verde { background-color: #1b5e20; }
.box-reserva { background-color: #ffd600; border: 1px solid #f57f17; }
.box-parada { background-color: #455a64; border: 1px solid #263238; }
.box-marca-amarilla { background-color: #ffb300; border: 1px solid #e65100; }
.box-marca-verde { background-color: #66bb6a; border: 1px solid #1b5e20; }
.box-fila-problema { background-color: #ffab91; border: 1px solid #d84315; }
.filter-input {
    width: 100%;
    box-sizing: border-box;
    margin-top: 6px;
    font-size: 11px;
    padding: 3px 4px;
    border: 1px solid #607d8b;
    border-radius: 3px;
    outline: none;
    font-family: inherit;
    font-weight: normal;
}
.filter-input:focus {
    border-color: #0d47a1;
    box-shadow: 0 0 0 2px rgba(13, 71, 161, 0.25);
}
.filter-select {
    width: 100%;
    box-sizing: border-box;
    margin-top: 6px;
    font-size: 11px;
    padding: 3px 18px 3px 4px;
    border: 1px solid #607d8b;
    border-radius: 3px;
    outline: none;
    font-family: inherit;
    font-weight: normal;
    color: #263238;
    background-color: #ffffff;
    cursor: pointer;
    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path d='M0 0L5 6L10 0Z' fill='%23455a64'/></svg>");
    background-repeat: no-repeat;
    background-position: right 5px center;
    background-size: 9px 6px;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.filter-select:hover {
    border-color: #607d8b;
}
.filter-select:focus {
    border-color: #0d47a1;
    box-shadow: 0 0 0 2px rgba(13, 71, 161, 0.25);
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path d='M0 0L5 6L10 0Z' fill='%230d47a1'/></svg>");
}
.filter-select option[value=""] {
    color: #78909c;
    font-style: italic;
}
.obs-col {
    min-width: 150px;
    max-width: 250px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    background-color: #fff9c4;
    cursor: text;
    text-align: left;
    padding-left: 8px;
    color: #263238;
    transition: background-color 0.3s;
}
.obs-col:hover {
    background-color: #ffe082;
}
.obs-edit-input {
    width: 100%;
    box-sizing: border-box;
    border: none;
    background-color: #ffffff;
    font-family: inherit;
    font-size: 12px;
    color: #263238;
    outline: 2px solid #0d47a1;
    padding: 2px 4px;
    border-radius: 2px;
}
.val-verde {
    color: #1b5e20 !important;
    font-weight: bold !important;
    cursor: pointer;
}
.val-reserva {
    color: #000000;
    font-weight: bold;
    background-color: #ffd600;
    border-radius: 3px;
    padding: 1px 4px;
    cursor: context-menu;
}
.val-parada {
    color: #ffffff;
    font-weight: bold;
    background-color: #455a64;
    border-radius: 3px;
    padding: 1px 4px;
    cursor: context-menu;
}
.menu-reserva {
    position: fixed;
    background: #ffffff;
    border: 1px solid #607d8b;
    border-radius: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    z-index: 1000;
    overflow: hidden;
    font-size: 13px;
}
.menu-reserva-item {
    padding: 8px 14px;
    cursor: pointer;
    white-space: nowrap;
    color: #263238;
}
.menu-reserva-item:hover {
    background-color: #cfd8dc;
}
.menu-reserva-sep {
    height: 1px;
    background: #b0bec5;
    margin: 2px 0;
}
tr.fila-problema td:not(.col-fixed-1):not(.col-fixed-2) {
    background-color: #ffab91;
}
tr.fila-sector td {
    padding: 6px 2px;
    font-weight: bold;
}
tr.fila-sector td.col-fixed-1,
tr.fila-sector td.col-fixed-2 {
    background-color: #455a64;
    color: #ffffff;
}
tr.fila-sector td:not(.col-fixed-1):not(.col-fixed-2) {
    background-color: #cfd8dc;
    color: #102027;
}
tr.fila-sector .sector-cell {
    cursor: default;
}
.day-cell.celda-marca-amarilla {
    background-color: #ffb300 !important;
}
.day-cell.celda-marca-verde {
    background-color: #66bb6a !important;
}
.day-cell {
    position: relative;
}
.celda-c-badge {
    position: absolute;
    top: 1px;
    font-size: 8px;
    font-weight: 800;
    color: #ffffff;
    width: 11px;
    height: 11px;
    line-height: 11px;
    border-radius: 2px;
    text-align: center;
    pointer-events: none;
    z-index: 5;
}
.celda-c-badge-comentario {
    right: 1px;
    background: #b71c1c;
    /* Icono rojo: permanece visible siempre que exista observación del técnico, también en días pasados */
    opacity: 1;
}
.celda-c-badge-guarda {
    left: 1px;
    background: #4a148c;
    /* Icono morado: oculto salvo al pasar el cursor por la celda (igual que en sectores 0, 1 y 2) */
    opacity: 0;
    transition: opacity 0.15s ease;
}
.day-cell:hover .celda-c-badge-guarda {
    opacity: 1;
}
/* Celda de HOY: la "C" del guarda se ve siempre, sin pasar el ratón.
   En días anteriores sigue apareciendo solo al pasar el ratón. */
.celda-c-badge-guarda.celda-c-badge-guarda-hoy {
    opacity: 1;
}
.tooltip-container {
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    margin-top: 8px;
    display: flex;
    gap: 6px;
    align-items: flex-start;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.15s ease;
    z-index: 999;
    white-space: nowrap;
}
.day-cell:hover .tooltip-container {
    opacity: 1;
}
.tooltip-bubble {
    padding: 5px 9px;
    border-radius: 6px;
    font-size: 11px;
    font-weight: 500;
    line-height: 1.3;
    box-shadow: 0 2px 8px rgba(0,0,0,0.25);
}
.tooltip-guarda {
    background: #263238;
    color: #ffffff;
}
.tooltip-comentario {
    background: #eceff1;
    color: #263238;
    border: 1px solid #607d8b;
}
.overlay-comentario {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000000;
}
.modal-comentario {
    background: #ffffff;
    border-radius: 8px;
    padding: 22px 24px 18px;
    width: 420px;
    max-width: 90vw;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
    font-family: Roboto, sans-serif;
}
.modal-comentario-titulo {
    font-size: 17px;
    font-weight: 700;
    color: #263238;
    margin-bottom: 4px;
}
.modal-comentario-sub {
    font-size: 13.5px;
    color: #607d8b;
    margin-bottom: 10px;
}
.modal-comentario-input {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid #b0bec5;
    border-radius: 4px;
    padding: 8px 10px;
    font-family: inherit;
    font-size: 13.5px;
    color: #263238;
    resize: vertical;
    outline: none;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.modal-comentario-input:focus {
    border-color: #1b5e20;
    box-shadow: 0 0 0 2px rgba(27, 94, 32, 0.2);
}
.modal-comentario-botones {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 16px;
}
.modal-btn {
    padding: 8px 18px;
    border-radius: 4px;
    border: none;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    font-family: inherit;
    transition: background 0.15s ease;
}
.modal-btn-cancelar {
    background: #eceff1;
    color: #37474f;
}
.modal-btn-cancelar:hover { background: #dfe4e8; }
.modal-btn-aceptar {
    background: #1b5e20;
    color: #ffffff;
}
.modal-btn-aceptar:hover { background: #144917; }
#tm-table {
    border-collapse: collapse;
    width: 100%;
    min-width: max-content;
}
#tm-table th, #tm-table td {
    box-sizing: border-box;
    border: 1px solid #78909c;
    padding: 4px 4px;
    text-align: center;
    font-size: 12px;
    min-width: 42px;
    height: 25px;
}
#tm-table th {
    background-color: #263238;
    color: #ffffff;
    font-weight: bold;
    position: sticky;
    top: 0;
    z-index: 10;
}
#tm-table .col-fixed.col-date {
    position: sticky;
    left: 0;
    z-index: 20;
    width: 45px;
    min-width: 45px;
    background-color: #263238;
    color: #ffffff;
}
#tm-table td.col-date {
    position: sticky;
    left: 0;
    background-color: #37474f;
    color: #ffffff;
    font-weight: bold;
    z-index: 5;
}
#tm-table .val-hoy { color: #1b5e20; font-weight: 700; }
#tm-table .sector-header-cell { background-color: #37474f !important; color: #ffffff; }

/* --- Calendario: letra algo más grande en los títulos (2026-10-19) ---
   Solo cambia el tamaño de letra, NO los anchos: las columnas fijas
   SECTOR (65px) y GRUPO (100px) mantienen su ancho, así que el widget no
   se hace más ancho que la pantalla. Si un nombre de grupo largo no cabe,
   pasa a dos líneas dentro de su celda (la fila crece un poco en alto). */
#irrigation-table thead th {
    font-size: 13px;
}
#irrigation-table td.col-fixed-1,
#irrigation-table td.col-fixed-2 {
    font-size: 13.5px;
    line-height: 1.2;
    overflow-wrap: anywhere; /* red de seguridad: solo parte una palabra si no cabe en el ancho fijo */
}

